36→  new Promise((resolve, reject) => {
37→    const attemptFetch = (attempt: number): void => {
38→      fetch(url, options)
39→        .then((res) => {
40→          if (res.ok) {
41→            return res.json();
42→          }
43→          reject(
44→            new Error(getErrorMessage(res, "GET"), {
45→              cause: { message: res.statusText, statusCode: res.status },
46→            }),
47→          );
48→        })
49→        .then((data) => resolve(data))
50→        .catch((err) => {
51→          if (attempt <= retries) {
52→            setTimeout(() => attemptFetch(attempt + 1), backoff * attempt);
53→          } else {
54→            reject(err);
55→          }
56→        });
57→    };
58→    attemptFetch(1);
59→  });
60→

 1→const getLocalStorageString = (key: string): string | undefined => {
 2→  try {
 3→    return localStorage.getItem(key) ?? undefined;
 4→  } catch {
 5→    return undefined;
 6→  }
 7→};
 8→
 9→const setLocalStorageString = (key: string, value: string): void => {
10→  try {
11→    localStorage.setItem(key, value);
12→  } catch {
13→    // Silently fail if localStorage is unavailable or full.
14→  }
15→};
